// #c937f5ca1b172513b5ce1e2d — /admin/providers доступен только Super Admin. Только просмотр, данные не меняет.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openWithApi } from '../support/api';

for (const role of ['business', 'user'] as const) {
  test.describe(`AI-провайдеры — доступ роли ${role} (#c937f5ca1b172513b5ce1e2d)`, () => {
    test.use({ storageState: path.resolve(__dirname, `../../../auth/${role}.json`) });

    test(`${role}: /admin/providers — «אין לך הרשאה למסך הזה», RPC 403 @desktop @prod-safe #c937f5ca1b172513b5ce1e2d`, async ({ page }) => {
      const api = await openWithApi(page, '/admin/providers');
      await expect(page.getByRole('heading', { level: 1, name: 'אין לך הרשאה למסך הזה' })).toBeVisible();
      await expect(page.getByRole('region', { name: 'הגדרת ספק' })).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'שמירת גרסה חדשה' })).toHaveCount(0);

      const res = await api.rpc('admin_list_provider_configs');
      expect(res.status()).toBe(403);
      expect(await res.text()).toContain('forbidden');
    });
  });
}
